  "evt.wedding.ms.paperwork": "Presentar el expediente matrimonial en el registro civil",
  "evt.wedding.ms.fittings": "Últimas pruebas, alianzas y plano de mesas",
  "evt.wedding.ms.confirm": "Confirmar proveedores y número final de asistentes",
  "evt.wedding.ms.dday": "El gran día 🎉",
  "evt.wedding.cheer.early": "Vais por delante del calendario: ese es el secreto de las bodas tranquilas. Cada euro que apartáis ahora es una opción más el gran día.",
  "evt.wedding.cheer.onTrack": "Vais por buen camino: el ahorro sigue el ritmo del calendario. Seguid así, esta es justo la versión sin estrés de una boda.",
  "evt.wedding.cheer.behind": "El ahorro va algo por detrás del calendario; sin pánico: subid la aportación mensual o ajustad una partida (la decoración y la papelería perdonan mucho más que el catering).",
  "evt.wedding.cheer.lastStretch": "¡Recta final! Confirmad el número de asistentes a los proveedores (cada invitado fantasma cuesta un menú) y no toquéis el margen de imprevistos.",
  "evt.travel.label": "Viaje",
  "evt.travel.tagline": "Transporte, alojamiento y gastos en destino: el presupuesto que evita sorpresas.",
  "evt.travel.guests": "Número de viajeros",
  "evt.travel.tier.low": "Mochilero",
  "evt.travel.tier.mid": "Confort",
  "evt.travel.tier.high": "Un capricho",
  "evt.travel.style.aventure.label": "🥾 Aventura barata",
  "evt.travel.style.aventure.tip": "Albergues, trenes locales y comida callejera: apunta a 30-40 € al día sin contar el transporte. Reserva el vuelo con 3-4 meses de antelación (salidas entre semana, aeropuertos secundarios) y viaja fuera de vacaciones escolares: la diferencia entre temporada alta y baja llega al 40 % en alojamiento.",
  "evt.travel.style.detente.label": "🏖️ Relax",
  "evt.travel.style.detente.tip": "Resorts y clubes: el todo incluido reservado con antelación casi siempre gana al pago a la carta. Compara el mismo hotel en dos o tres plataformas y en su web directa, y anota aquí los precios para ver la tendencia.",
  "evt.travel.style.culture.label": "🏛️ Escapada cultural",
  "evt.travel.style.culture.tip": "Las tarjetas turísticas (museos y transporte) se amortizan a partir de dos visitas al día. Alójate cerca de una línea de metro en vez de en pleno centro: un 30 % menos de alojamiento por quince minutos de trayecto.",
  "evt.travel.style.famille.label": "👨‍👩‍👧 En familia",
  "evt.travel.style.famille.tip": "A partir de cuatro personas, un apartamento con cocina gana al hotel (comer fuera es la partida que se dispara). Comprueba las gratuidades para niños del país (transporte, museos): a menudo hasta los 12 años.",
  "evt.travel.item.transport": "Transporte ida y vuelta (por persona)",
  "evt.travel.item.lodging": "Alojamiento (estancia completa, por persona)",
  "evt.travel.item.food": "Comidas y salidas (por persona)",
  "evt.travel.item.activities": "Actividades y visitas (por persona)",
  "evt.travel.item.insurance": "Seguro de viaje",
  "evt.travel.item.visa": "Visados y trámites",
  "evt.travel.item.localTransport": "Transporte en destino",
  "evt.travel.item.buffer": "Imprevistos (10 %)",
  "evt.travel.ms.destination": "Elegir el destino y fijar las fechas",
  "evt.travel.ms.transport": "Reservar el transporte (después los precios suben)",
  "evt.travel.ms.lodging": "Reservar los alojamientos",
  "evt.travel.ms.documents": "Revisar pasaportes, visados y vacunas",
  "evt.travel.ms.insurance": "Contratar el seguro y avisar al banco",
  "evt.travel.ms.departure": "Salida 🧳",
  "evt.travel.cheer.early": "Reservar pronto es el mejor chollo del viaje: los billetes no esperarán a que tu ahorro esté listo.",
  "evt.travel.cheer.onTrack": "El presupuesto del viaje se llena al ritmo adecuado: las vacaciones se disfrutan mucho más cuando ya están pagadas.",
  "evt.travel.cheer.behind": "El ahorro va algo justo: cubre primero el transporte y el alojamiento (las partidas que se disparan); el resto puede ajustarse allí.",
  "evt.travel.cheer.lastStretch": "¡Ya casi te vas! Revisa la documentación, descarga las reservas para verlas sin conexión y guarda la partida de imprevistos para las sorpresas de verdad.",
