  "evt.funeral.ms.ceremony": "Ceremonia",
  "evt.funeral.cheer.early": "Prever es proteger a los tuyos: un presupuesto hecho con calma evita decisiones caras tomadas con prisa y con dolor.",
  "evt.funeral.cheer.onTrack": "El presupuesto detallado es tu mejor aliado: las funerarias deben facilitártelo gratis; pide varios, las diferencias son enormes.",
  "evt.funeral.cheer.behind": "No dejes que te metan prisa: solo unos pocos servicios son obligatorios por ley, todo lo demás es negociable. Y existen ayudas (auxilio por defunción, cargo a la cuenta del fallecido).",
  "evt.funeral.cheer.lastStretch": "Ánimo. Céntrate en lo esencial, deja que alguien te ayude con los trámites y revisa cada línea del presupuesto final antes de firmar.",
