  "evt.party.style.enfant.tip": "El gasto habitual en casa ronda los 200 € en total. El animador profesional (200-300 €) es la partida decisiva: a los cinco años, unos juegos organizados por dos adultos hacen el mismo efecto.",
  "evt.party.style.adulte.label": "🥂 Adultos",
  "evt.party.style.adulte.tip": "Un cóctel de pie cuesta la mitad que una cena sentada y hace que la gente circule. Pide que cada uno traiga una botella: clásico y eficaz.",
  "evt.party.style.surprise.label": "🎁 Sorpresa",
  "evt.party.style.surprise.tip": "Presupuesto secreto significa pagos discretos y repartidos. Crea el evento en tu espacio personal (¡no en el compartido!) para que la sorpresa siga siendo sorpresa.",
