  "evt.party.ms.dday": "El gran día 🎉",
  "evt.party.cheer.early": "Una buena fiesta se decide en la lista de invitados: es la que manda en todo el presupuesto. Ciérrala primero y lo demás vendrá solo.",
  "evt.party.cheer.onTrack": "Todo en marcha: la fiesta se financia al buen ritmo. Hacer en casa la decoración y la tarta suele costar la mitad.",
  "evt.party.cheer.behind": "El ahorro va un poco justo: recorta una partida de capricho (decoración, animación) antes que el número de amigos: ellos son la fiesta.",
  "evt.party.cheer.lastStretch": "Recta final: confirma quién viene antes de hacer la compra, así no acabas dando de comer a veinte fantasmas.",
