  "evt.religious.ms.dday": "Día de la fiesta ✨",
  "evt.religious.cheer.early": "Ahorrar con varios meses de antelación es la mejor defensa contra la subida de precios previa a la fiesta: compras cuando todo está tranquilo.",
  "evt.religious.cheer.onTrack": "El ahorro específico avanza bien: la fiesta será bonita Y sin deudas. Ese es justo el espíritu.",
  "evt.religious.cheer.behind": "El ahorro va con retraso: mejor una fiesta algo más sencilla que un crédito que devolver después; nadie recuerda el precio, todos recuerdan el momento.",
  "evt.religious.cheer.lastStretch": "Ya casi es el gran día: las últimas compras en el mercado se negocian mejor por la mañana, y una lista escrita evita los extras.",
